<body>
  <h1>Aggregated Heartbeat Dashboard</h1>
  <div style="text-align:center; margin-bottom:1rem;">
    <label>Server 1 API Base URL: <input id="url1" value="http://localhost:9100" /></label>
    <label>Server 2 API Base URL: <input id="url2" value="http://localhost:9101" /></label>
    <button onclick="refreshAll()">Refresh Now</button>
  </div>
  <div class="servers">
    <div class="server" id="server1">
      <div class="status"><span class="light offline" id="light1"></span>Server 1: <span id="status1">Loading...</span></div>
      <div>Heartbeat: <span class="heartbeat" id="heartbeat1">-</span></div>
      <div class="log" id="log1">-</div>
    </div>
    <div class="server" id="server2">
      <div class="status"><span class="light offline" id="light2"></span>Server 2: <span id="status2">Loading...</span></div>
      <div>Heartbeat: <span class="heartbeat" id="heartbeat2">-</span></div>
      <div class="log" id="log2">-</div>
    </div>
  </div>
  <script>
    function setLight(idx, online) {
      const lightEl = document.getElementById('light' + idx);
      lightEl.className = 'light ' + (online ? 'online' : 'offline');
    }

    async function fetchStatus(idx, baseUrl) {
      const statusEl = document.getElementById('status'+idx);
      const heartbeatEl = document.getElementById('heartbeat'+idx);
      const logEl = document.getElementById('log'+idx);
      try {
        const [hb, st] = await Promise.all([
          fetch(baseUrl + '/api/heartbeat').then(r => r.json()),
          fetch(baseUrl + '/api/status').then(r => r.json())
        ]);
        if (hb.heartbeat) {
          statusEl.textContent = 'Online';
          statusEl.className = '';
          setLight(idx, true);
          heartbeatEl.textContent = hb.heartbeat;
        } else {
          statusEl.textContent = 'No Heartbeat';
          statusEl.className = 'error';
          setLight(idx, false);
          heartbeatEl.textContent = '-';
        }
        if (st.status) {
          logEl.textContent = st.status;
        } else {
          logEl.textContent = st.error || '-';
        }
      } catch (e) {
        statusEl.textContent = 'Offline';
        statusEl.className = 'error';
        setLight(idx, false);
        heartbeatEl.textContent = '-';
        logEl.textContent = e.message;
      }
    }
    function refreshAll() {
      const url1 = document.getElementById('url1').value;
      const url2 = document.getElementById('url2').value;
      fetchStatus(1, url1);
      fetchStatus(2, url2);
    }
    setInterval(refreshAll, 3000);
    window.onload = refreshAll;
  </script>
</body>
</html>
